import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class DayCounter {
    public static long daysBetween(LocalDate from, LocalDate to) {
        if (from == null || to == null) {
            throw new IllegalArgumentException("dates must not be null");
        }
        return ChronoUnit.DAYS.between(from, to);
    }
}

test:
public class Test {
    public static void main(String[] a) {
        java.time.LocalDate d = java.time.LocalDate.of(2026, 1, 1);
        if (!(DayCounter.daysBetween(d, java.time.LocalDate.of(2026, 3, 1)) == 59)) throw new AssertionError("normal");
        try { DayCounter.daysBetween(null, d); throw new AssertionError("null from accepted"); }
        catch (IllegalArgumentException expected) { }
        try { DayCounter.daysBetween(d, null); throw new AssertionError("null to accepted"); }
        catch (IllegalArgumentException expected) { }
        System.out.println("PASS");
    }
}
